    ('捍卫', '捍衛', 'hàn wèi', 'han wei hanwei han4 wei4 han4wei4', 'hãn vệ', 'Động từ', 'bảo vệ vững chắc', 6, 28, '我们要捍卫自己的权利。', 'wǒ men yào hàn wèi zì jǐ de quán lì 。', 'Chúng ta cần bảo vệ quyền lợi của mình.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('履行', '履行', 'lǚ xíng', 'lv xing lvxing lv3 xing2 lv3xing2', 'lý hành', 'Động từ', 'thực hiện, thi hành', 6, 28, '他认真履行职责。', 'tā rèn zhēn lǚ xíng zhí zé 。', 'Anh ấy nghiêm túc thực hiện chức trách.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('造诣', '造詣', 'zào yì', 'zao yi zaoyi zao4 yi4 zao4yi4', 'tạo nghệ', 'Danh từ', 'trình độ thành tựu', 6, 29, '他在书法方面造诣很深。', 'tā zài shū fǎ fāng miàn zào yì hěn shēn 。', 'Anh ấy có trình độ rất sâu về thư pháp.', 'hsk6-classical-idioms-rhetoric', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('棘手', '棘手', 'jí shǒu', 'ji shou jishou ji2 shou3 ji2shou3', 'cức thủ', 'Tính từ', 'khó giải quyết', 6, 28, '这是一个棘手的问题。', 'zhè shì yí gè jí shǒu de wèn tí 。', 'Đây là một vấn đề khó giải quyết.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('侥幸', '僥倖', 'jiǎo xìng', 'jiao xing jiaoxing jiao3 xing4 jiao3xing4', 'kiểu hạnh', 'Phó từ', 'may mắn tình cờ, cầu may', 6, 28, '他侥幸通过了考试。', 'tā jiǎo xìng tōng guò le kǎo shì 。', 'Anh ấy may mắn vượt qua kỳ thi.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('敷衍', '敷衍', 'fū yǎn', 'fu yan fuyan fu1 yan3 fu1yan3', 'phu diễn', 'Động từ', 'làm qua loa', 6, 28, '不要敷衍自己的工作。', 'bú yào fū yǎn zì jǐ de gōng zuò 。', 'Đừng làm công việc của mình qua loa.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('瞻仰', '瞻仰', 'zhān yǎng', 'zhan yang zhanyang zhan1 yang3 zhan1yang3', 'chiêm ngưỡng', 'Động từ', 'chiêm ngưỡng với lòng kính trọng', 6, 29, '大家前来瞻仰纪念碑。', 'dà jiā qián lái zhān yǎng jì niàn bēi 。', 'Mọi người đến chiêm ngưỡng đài tưởng niệm với lòng kính trọng.', 'hsk6-classical-idioms-rhetoric', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('震撼', '震撼', 'zhèn hàn', 'zhen han zhenhan zhen4 han4 zhen4han4', 'chấn hám', 'Động từ', 'chấn động', 6, 28, '这场演出震撼了观众。', 'zhè chǎng yǎn chū zhèn hàn le guān zhòng 。', 'Buổi biểu diễn này làm khán giả chấn động.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('融洽', '融洽', 'róng qià', 'rong qia rongqia rong2 qia4 rong2qia4', 'dung hiệp', 'Tính từ', 'hòa thuận', 6, 28, '他们的关系很融洽。', 'tā men de guān xì hěn róng qià 。', 'Quan hệ của họ rất hòa thuận.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('安居乐业', '安居樂業', 'ān jū lè yè', 'an ju le ye anjuleye an1 ju1 le4 ye4 an1ju1le4ye4', 'an cư lạc nghiệp', 'Thành ngữ', 'an cư lạc nghiệp', 6, 29, '人人都希望安居乐业。', 'rén rén dōu xī wàng ān jū lè yè 。', 'Ai cũng mong an cư lạc nghiệp.', 'hsk6-classical-idioms-rhetoric', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('半途而废', '半途而廢', 'bàn tú ér fèi', 'ban tu er fei bantuerfei ban4 tu2 er2 fei4 ban4tu2er2fei4', 'bán đồ nhi phế', 'Thành ngữ', 'bỏ dở giữa chừng', 6, 29, '学习不能半途而废。', 'xué xí bù néng bàn tú ér fèi 。', 'Học tập không thể bỏ dở giữa chừng.', 'hsk6-classical-idioms-rhetoric', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('不言而喻', '不言而喻', 'bù yán ér yù', 'bu yan er yu buyaneryu bu4 yan2 er2 yu4 bu4yan2er2yu4', 'bất ngôn nhi dụ', 'Thành ngữ', 'không nói cũng hiểu', 6, 29, '健康的重要性不言而喻。', 'jiàn kāng de zhòng yào xìng bù yán ér yù 。', 'Tầm quan trọng của sức khỏe không nói cũng hiểu.', 'hsk6-classical-idioms-rhetoric', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('层出不穷', '層出不窮', 'céng chū bù qióng', 'ceng chu bu qiong cengchubuqiong ceng2 chu1 bu4 qiong2 ceng2chu1bu4qiong2', 'tầng xuất bất cùng', 'Thành ngữ', 'xuất hiện liên tiếp không dứt', 6, 29, '新的想法层出不穷。', 'xīn de xiǎng fǎ céng chū bù qióng 。', 'Ý tưởng mới xuất hiện liên tiếp không dứt.', 'hsk6-classical-idioms-rhetoric', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('从容不迫', '從容不迫', 'cóng róng bù pò', 'cong rong bu po congrongbupo cong2 rong2 bu4 po4 cong2rong2bu4po4', 'tòng dung bất bách', 'Thành ngữ', 'ung dung, bình tĩnh', 6, 29, '她从容不迫地回答问题。', 'tā cóng róng bù pò dì huí dá wèn tí 。', 'Cô ấy bình tĩnh trả lời câu hỏi.', 'hsk6-classical-idioms-rhetoric', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('颁布', '頒布', 'bān bù', 'ban bu banbu ban1 bu4 ban1bu4', 'ban bố', 'Động từ', 'ban bố', 6, 28, '新规定已经颁布。', 'xīn guī dìng yǐ jīng bān bù 。', 'Quy định mới đã được ban bố.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('弊端', '弊端', 'bì duān', 'bi duan biduan bi4 duan1 bi4duan1', 'tệ đoan', 'Danh từ', 'điểm bất cập', 6, 28, '我们需要消除这些弊端。', 'wǒ men xū yào xiāo chú zhè xiē bì duān 。', 'Chúng ta cần loại bỏ những bất cập này.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('财政', '財政', 'cái zhèng', 'cai zheng caizheng cai2 zheng4 cai2zheng4', 'tài chính', 'Danh từ', 'tài chính công', 6, 28, '报告讨论了财政问题。', 'bào gào tǎo lùn le cái zhèng wèn tí 。', 'Báo cáo đã bàn về vấn đề tài chính công.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('策略', '策略', 'cè lüè', 'ce lve celve ce4 lve4 ce4lve4', 'sách lược', 'Danh từ', 'sách lược', 6, 28, '我们需要调整策略。', 'wǒ men xū yào tiáo zhěng cè lüè 。', 'Chúng ta cần điều chỉnh sách lược.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('阐述', '闡述', 'chǎn shù', 'chan shu chanshu chan3 shu4 chan3shu4', 'xiển thuật', 'Động từ', 'trình bày rõ', 6, 28, '请阐述你的理由。', 'qǐng chǎn shù nǐ de lǐ yóu 。', 'Xin trình bày rõ lý do của bạn.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('创新', '創新', 'chuàng xīn', 'chuang xin chuangxin chuang4 xin1 chuang4xin1', 'sáng tân', 'Động từ', 'đổi mới, sáng tạo', 6, 28, '这个团队不断创新。', 'zhè ge tuán duì bù duàn chuàng xīn 。', 'Nhóm này không ngừng đổi mới.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('筹备', '籌備', 'chóu bèi', 'chou bei choubei chou2 bei4 chou2bei4', 'trù bị', 'Động từ', 'trù bị, chuẩn bị', 6, 28, '他们正在筹备会议。', 'tā men zhèng zài chóu bèi huì yì 。', 'Họ đang chuẩn bị hội nghị.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('承诺', '承諾', 'chéng nuò', 'cheng nuo chengnuo cheng2 nuo4 cheng2nuo4', 'thừa nặc', 'Danh từ', 'cam kết', 6, 28, '他履行了自己的承诺。', 'tā lǚ xíng le zì jǐ de chéng nuò 。', 'Anh ấy đã thực hiện cam kết của mình.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('储备', '儲備', 'chǔ bèi', 'chu bei chubei chu3 bei4 chu3bei4', 'trữ bị', 'Động từ', 'dự trữ', 6, 28, '我们需要储备粮食。', 'wǒ men xū yào chǔ bèi liáng shí 。', 'Chúng ta cần dự trữ lương thực.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md'),
    ('倡导', '倡導', 'chàng dǎo', 'chang dao changdao chang4 dao3 chang4dao3', 'xướng đạo', 'Động từ', 'đề xướng', 6, 28, '学校倡导节约用水。', 'xué xiào chàng dǎo jié yuē yòng shuǐ 。', 'Nhà trường đề xướng tiết kiệm nước.', 'hsk6-academic-governance', 'APPROVED', false, 'M6:thematic;HSK2.0-ref;docs/m6-curriculum-sources.md')
) AS v(word,traditional,pinyin,pinyin_normalized,han_viet,part_of_speech,meaning_vi,hsk_level,lesson_number,example_zh,example_pinyin,example_vi,lesson_slug,review_status,needs_human_check,source_ref)
JOIN lessons l ON l.slug=v.lesson_slug
WHERE NOT EXISTS (SELECT 1 FROM vocabulary old WHERE old.word=v.word AND old.hsk_level=v.hsk_level AND old.lesson_id IS NOT NULL);

INSERT INTO grammar_rules (title,structure,hsk_level,explanation_vi,explanation,examples_json,exercises_json,notes,order_index,lesson_id,review_status,source_ref)
SELECT r.title,r.structure,r.hsk_level,r.explanation_vi,r.explanation,r.examples_json,r.exercises_json,r.notes,r.order_index,l.id,r.review_status,r.source_ref
FROM (VALUES
    ('Câu chữ 把', 'S + 把 + O + V + kết quả / vị trí', 3, 'Đưa tân ngữ đã xác định lên trước động từ để nói cách xử lý và kết quả tác động lên nó. Động từ thường cần thêm kết quả, vị trí hoặc thành phần hoàn thành.', 'Đưa tân ngữ đã xác định lên trước động từ để nói cách xử lý và kết quả tác động lên nó. Động từ thường cần thêm kết quả, vị trí hoặc thành phần hoàn thành.', '[{"zh":"请把书放在桌子上。","pinyin":"qǐng bǎ shū fàng zài zhuō zi shàng 。","vi":"Xin đặt sách lên bàn."},{"zh":"我把作业写完了。","pinyin":"wǒ bǎ zuò yè xiě wán le 。","vi":"Tôi đã làm xong bài tập."}]', '[{"question":"请___门关上。","options":["把","被","比","从"],"answer":"把","explanation":"Đưa tân ngữ đã xác định lên trước động từ để nói cách xử lý và kết quả tác động lên nó. Động từ thường cần thêm kết quả, vị trí hoặc thành phần hoàn thành. Lưu ý: Không dịch mọi câu “lấy” thành 把. Không để câu kết thúc bằng một động từ trần khi chưa diễn đạt kết quả xử lý."},{"question":"我把作业写___了。","options":["在","从","给","完"],"answer":"完","explanation":"Đưa tân ngữ đã xác định lên trước động từ để nói cách xử lý và kết quả tác động lên nó. Động từ thường cần thêm kết quả, vị trí hoặc thành phần hoàn thành. Lưu ý: Không dịch mọi câu “lấy” thành 把. Không để câu kết thúc bằng một động từ trần khi chưa diễn đạt kết quả xử lý."}]', 'Lỗi thường gặp của người Việt: Không dịch mọi câu “lấy” thành 把. Không để câu kết thúc bằng một động từ trần khi chưa diễn đạt kết quả xử lý.', 19, 'hsk3-life-environment', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Câu bị động với 被', 'O + 被 + (tác nhân) + V + thành phần khác', 3, 'Đặt đối tượng chịu tác động làm chủ ngữ. Tác nhân sau 被 có thể được lược bỏ khi ngữ cảnh rõ. Câu thường có thành phần diễn đạt kết quả.', 'Đặt đối tượng chịu tác động làm chủ ngữ. Tác nhân sau 被 có thể được lược bỏ khi ngữ cảnh rõ. Câu thường có thành phần diễn đạt kết quả.', '[{"zh":"我的自行车被偷了。","pinyin":"wǒ de zì xíng chē bèi tōu le 。","vi":"Xe đạp của tôi bị trộm rồi."},{"zh":"门被风吹开了。","pinyin":"mén bèi fēng chuī kāi le 。","vi":"Cửa bị gió thổi mở ra."}]', '[{"question":"门___风吹开了。","options":["把","给","比","被"],"answer":"被","explanation":"Đặt đối tượng chịu tác động làm chủ ngữ. Tác nhân sau 被 có thể được lược bỏ khi ngữ cảnh rõ. Câu thường có thành phần diễn đạt kết quả. Lưu ý: Chủ ngữ là đối tượng chịu tác động, không phải người thực hiện. Phủ định 没 đứng trước 被."},{"question":"我的书___被拿走。","options":["比","从","没","把"],"answer":"没","explanation":"Đặt đối tượng chịu tác động làm chủ ngữ. Tác nhân sau 被 có thể được lược bỏ khi ngữ cảnh rõ. Câu thường có thành phần diễn đạt kết quả. Lưu ý: Chủ ngữ là đối tượng chịu tác động, không phải người thực hiện. Phủ định 没 đứng trước 被."}]', 'Lỗi thường gặp của người Việt: Chủ ngữ là đối tượng chịu tác động, không phải người thực hiện. Phủ định 没 đứng trước 被.', 20, 'hsk3-life-environment', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Bổ ngữ xu hướng kép', 'V + 起来 / 下去 / 出来', 3, 'Bổ ngữ xu hướng mô tả hướng chuyển động so với vị trí người nói. Một số tổ hợp còn chỉ bắt đầu hoặc tiếp tục một trạng thái, cần đọc theo ngữ cảnh.', 'Bổ ngữ xu hướng mô tả hướng chuyển động so với vị trí người nói. Một số tổ hợp còn chỉ bắt đầu hoặc tiếp tục một trạng thái, cần đọc theo ngữ cảnh.', '[{"zh":"他从房间里走出来。","pinyin":"tā cóng fáng jiān lǐ zǒu chū lái 。","vi":"Anh ấy đi từ trong phòng ra."},{"zh":"请继续说下去。","pinyin":"qǐng jì xù shuō xià qù 。","vi":"Xin tiếp tục nói."}]', '[{"question":"他从房间里走___。","options":["不上","得很","出来","进去"],"answer":"出来","explanation":"Bổ ngữ xu hướng mô tả hướng chuyển động so với vị trí người nói. Một số tổ hợp còn chỉ bắt đầu hoặc tiếp tục một trạng thái, cần đọc theo ngữ cảnh. Lưu ý: Không dịch 来 và 去 đơn thuần là thời tương lai. 来 thường hướng về người nói, 去 hướng ra xa người nói."},{"question":"故事还没结束，请继续说___。","options":["得","下去","上来","不过"],"answer":"下去","explanation":"Bổ ngữ xu hướng mô tả hướng chuyển động so với vị trí người nói. Một số tổ hợp còn chỉ bắt đầu hoặc tiếp tục một trạng thái, cần đọc theo ngữ cảnh. Lưu ý: Không dịch 来 và 去 đơn thuần là thời tương lai. 来 thường hướng về người nói, 去 hướng ra xa người nói."}]', 'Lỗi thường gặp của người Việt: Không dịch 来 và 去 đơn thuần là thời tương lai. 来 thường hướng về người nói, 去 hướng ra xa người nói.', 21, 'hsk3-life-environment', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Loại trừ và bổ sung với 除了', '除了 A 以外，S + 都 / 还 / 也…', 3, '除了…以外 nêu phạm vi ngoại lệ hoặc bổ sung. 都 thường dẫn phần còn lại trong câu loại trừ, còn 还 hoặc 也 thường bổ sung đối tượng hoặc hoạt động khác.', '除了…以外 nêu phạm vi ngoại lệ hoặc bổ sung. 都 thường dẫn phần còn lại trong câu loại trừ, còn 还 hoặc 也 thường bổ sung đối tượng hoặc hoạt động khác.', '[{"zh":"除了小王以外，大家都来了。","pinyin":"chú le xiǎo wáng yǐ wài ， dà jiā dōu lái le 。","vi":"Trừ Tiểu Vương, mọi người đều đến rồi."},{"zh":"除了汉语以外，我还学英语。","pinyin":"chú le hàn yǔ yǐ wài ， wǒ hái xué yīng yǔ 。","vi":"Ngoài tiếng Hán, tôi còn học tiếng Anh."}]', '[{"question":"除了小王以外，大家___来了。","options":["的","都","把","被"],"answer":"都","explanation":"除了…以外 nêu phạm vi ngoại lệ hoặc bổ sung. 都 thường dẫn phần còn lại trong câu loại trừ, còn 还 hoặc 也 thường bổ sung đối tượng hoặc hoạt động khác. Lưu ý: Đừng luôn dịch 除了 là “trừ”. Cần dựa vào 都 hay 还 và ngữ cảnh để xác định loại trừ hoặc bổ sung."},{"question":"除了汉语以外，我___学英语。","options":["还","把","被","地"],"answer":"还","explanation":"除了…以外 nêu phạm vi ngoại lệ hoặc bổ sung. 都 thường dẫn phần còn lại trong câu loại trừ, còn 还 hoặc 也 thường bổ sung đối tượng hoặc hoạt động khác. Lưu ý: Đừng luôn dịch 除了 là “trừ”. Cần dựa vào 都 hay 还 và ngữ cảnh để xác định loại trừ hoặc bổ sung."}]', 'Lỗi thường gặp của người Việt: Đừng luôn dịch 除了 là “trừ”. Cần dựa vào 都 hay 还 và ngữ cảnh để xác định loại trừ hoặc bổ sung.', 22, 'hsk3-life-environment', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Tăng tiến với 越', '越来越 + tính từ / 越 A 越 B', 3, '越来越 nêu sự thay đổi tăng dần theo thời gian. 越 A 越 B cho biết mức độ của B thay đổi theo mức độ hoặc hoạt động A.', '越来越 nêu sự thay đổi tăng dần theo thời gian. 越 A 越 B cho biết mức độ của B thay đổi theo mức độ hoặc hoạt động A.', '[{"zh":"天气越来越冷了。","pinyin":"tiān qì yuè lái yuè lěng le 。","vi":"Thời tiết càng ngày càng lạnh."},{"zh":"这本书越看越有意思。","pinyin":"zhè běn shū yuè kàn yuè yǒu yì si 。","vi":"Quyển sách này càng đọc càng thú vị."}]', '[{"question":"天气___冷了。","options":["越来越","很越","越很","越来"],"answer":"越来越","explanation":"越来越 nêu sự thay đổi tăng dần theo thời gian. 越 A 越 B cho biết mức độ của B thay đổi theo mức độ hoặc hoạt động A. Lưu ý: Không chèn 很 ngay sau 越来越. Trong 越 A 越 B phải giữ cả hai chữ 越."},{"question":"这本书越看___有意思。","options":["很越","比","把","越"],"answer":"越","explanation":"越来越 nêu sự thay đổi tăng dần theo thời gian. 越 A 越 B cho biết mức độ của B thay đổi theo mức độ hoặc hoạt động A. Lưu ý: Không chèn 很 ngay sau 越来越. Trong 越 A 越 B phải giữ cả hai chữ 越."}]', 'Lỗi thường gặp của người Việt: Không chèn 很 ngay sau 越来越. Trong 越 A 越 B phải giữ cả hai chữ 越.', 23, 'hsk3-life-environment', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Không những… mà còn…', '不但…而且…', 3, 'Nối hai đặc điểm hoặc sự việc theo quan hệ bổ sung tăng tiến. Khi hai vế cùng chủ ngữ, chủ ngữ thường đặt trước 不但. Khi khác chủ ngữ, 不但 có thể đứng trước chủ ngữ thứ nhất.', 'Nối hai đặc điểm hoặc sự việc theo quan hệ bổ sung tăng tiến. Khi hai vế cùng chủ ngữ, chủ ngữ thường đặt trước 不但. Khi khác chủ ngữ, 不但 có thể đứng trước chủ ngữ thứ nhất.', '[{"zh":"她不但会说汉语，而且会写汉字。","pinyin":"tā bù dàn huì shuō hàn yǔ ， ér qiě huì xiě hàn zì 。","vi":"Cô ấy không những biết nói tiếng Hán mà còn biết viết chữ Hán."},{"zh":"不但我喜欢，妹妹也喜欢。","pinyin":"bù dàn wǒ xǐ huān ， mèi mèi yě xǐ huān 。","vi":"Không chỉ tôi thích, em gái cũng thích."}]', '[{"question":"她不但会说汉语，___会写汉字。","options":["但是","所以","因为","而且"],"answer":"而且","explanation":"Nối hai đặc điểm hoặc sự việc theo quan hệ bổ sung tăng tiến. Khi hai vế cùng chủ ngữ, chủ ngữ thường đặt trước 不但. Khi khác chủ ngữ, 不但 có thể đứng trước chủ ngữ thứ nhất. Lưu ý: Đừng dùng 但是 thay 而且 khi hai vế cùng chiều bổ sung, không có ý đối lập."},{"question":"___我喜欢，妹妹也喜欢。","options":["被","比","不但","把"],"answer":"不但","explanation":"Nối hai đặc điểm hoặc sự việc theo quan hệ bổ sung tăng tiến. Khi hai vế cùng chủ ngữ, chủ ngữ thường đặt trước 不但. Khi khác chủ ngữ, 不但 có thể đứng trước chủ ngữ thứ nhất. Lưu ý: Đừng dùng 但是 thay 而且 khi hai vế cùng chiều bổ sung, không có ý đối lập."}]', 'Lỗi thường gặp của người Việt: Đừng dùng 但是 thay 而且 khi hai vế cùng chiều bổ sung, không có ý đối lập.', 24, 'hsk3-life-environment', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Nhượng bộ với 尽管', '尽管…但是 / 还是…', 4, 'Thừa nhận một điều kiện đã có rồi nêu kết quả trái với điều thường dự đoán. 尽管 cũng có cách dùng cho phép cứ làm, bài này tập trung vào quan hệ nhượng bộ.', 'Thừa nhận một điều kiện đã có rồi nêu kết quả trái với điều thường dự đoán. 尽管 cũng có cách dùng cho phép cứ làm, bài này tập trung vào quan hệ nhượng bộ.', '[{"zh":"尽管下雨，他还是出门了。","pinyin":"jǐn guǎn xià yǔ ， tā hái shì chū mén le 。","vi":"Mặc dù mưa, anh ấy vẫn ra ngoài."},{"zh":"尽管很难，但是我们没有放弃。","pinyin":"jǐn guǎn hěn nán ， dàn shì wǒ men méi yǒu fàng qì 。","vi":"Mặc dù rất khó, chúng tôi không bỏ cuộc."}]', '[{"question":"___下雨，他还是出门了。","options":["既然","按照","尽管","因为"],"answer":"尽管","explanation":"Thừa nhận một điều kiện đã có rồi nêu kết quả trái với điều thường dự đoán. 尽管 cũng có cách dùng cho phép cứ làm, bài này tập trung vào quan hệ nhượng bộ. Lưu ý: Không suy ra kết quả tất yếu như 因为…所以. Vế sau cần có ý ngược với kỳ vọng từ vế trước."},{"question":"尽管很累，他___坚持工作。","options":["因为","还是","所以","因此"],"answer":"还是","explanation":"Thừa nhận một điều kiện đã có rồi nêu kết quả trái với điều thường dự đoán. 尽管 cũng có cách dùng cho phép cứ làm, bài này tập trung vào quan hệ nhượng bộ. Lưu ý: Không suy ra kết quả tất yếu như 因为…所以. Vế sau cần có ý ngược với kỳ vọng từ vế trước."}]', 'Lỗi thường gặp của người Việt: Không suy ra kết quả tất yếu như 因为…所以. Vế sau cần có ý ngược với kỳ vọng từ vế trước.', 25, 'hsk4-career-society', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Bất kể với 不管 / 无论', '不管 / 无论 + điều kiện biến đổi + 都…', 4, 'Khẳng định kết quả không đổi trước các khả năng khác nhau. Điều kiện thường dùng từ nghi vấn phiếm chỉ như 谁, 怎么, 多… hoặc hai phương án đối lập.', 'Khẳng định kết quả không đổi trước các khả năng khác nhau. Điều kiện thường dùng từ nghi vấn phiếm chỉ như 谁, 怎么, 多… hoặc hai phương án đối lập.', '[{"zh":"不管多忙，我都每天读书。","pinyin":"bù guǎn duō máng ， wǒ dōu měi tiān dú shū 。","vi":"Dù bận thế nào, tôi cũng đọc sách mỗi ngày."},{"zh":"无论谁来，我们都欢迎。","pinyin":"wú lùn shuí lái ， wǒ men dōu huān yíng 。","vi":"Bất luận ai đến, chúng tôi đều hoan nghênh."}]', '[{"question":"不管多忙，我___每天读书。","options":["的","都","把","被"],"answer":"都","explanation":"Khẳng định kết quả không đổi trước các khả năng khác nhau. Điều kiện thường dùng từ nghi vấn phiếm chỉ như 谁, 怎么, 多… hoặc hai phương án đối lập. Lưu ý: Không bỏ 都 trong mẫu luyện này. Đừng nhầm 谁 trong 无论谁 với một câu hỏi trực tiếp."},{"question":"___谁来，我们都欢迎。","options":["无论","既然","按照","因为"],"answer":"无论","explanation":"Khẳng định kết quả không đổi trước các khả năng khác nhau. Điều kiện thường dùng từ nghi vấn phiếm chỉ như 谁, 怎么, 多… hoặc hai phương án đối lập. Lưu ý: Không bỏ 都 trong mẫu luyện này. Đừng nhầm 谁 trong 无论谁 với một câu hỏi trực tiếp."}]', 'Lỗi thường gặp của người Việt: Không bỏ 都 trong mẫu luyện này. Đừng nhầm 谁 trong 无论谁 với một câu hỏi trực tiếp.', 26, 'hsk4-career-society', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Suy luận với 既然', '既然…就…', 4, 'Lấy một sự việc đã được thừa nhận làm tiền đề cho lời đề nghị hoặc kết luận. 既然 thiên về “đã như thế thì”, không chỉ nêu nguyên nhân khách quan.', 'Lấy một sự việc đã được thừa nhận làm tiền đề cho lời đề nghị hoặc kết luận. 既然 thiên về “đã như thế thì”, không chỉ nêu nguyên nhân khách quan.', '[{"zh":"既然来了，就坐一会儿吧。","pinyin":"jì rán lái le ， jiù zuò yī huì er ba 。","vi":"Đã đến rồi thì ngồi một lát nhé."},{"zh":"既然你同意，我们就开始。","pinyin":"jì rán nǐ tóng yì ， wǒ men jiù kāi shǐ 。","vi":"Bạn đã đồng ý thì chúng ta bắt đầu."}]', '[{"question":"既然来了，___坐一会儿吧。","options":["就","因为","虽然","尽管"],"answer":"就","explanation":"Lấy một sự việc đã được thừa nhận làm tiền đề cho lời đề nghị hoặc kết luận. 既然 thiên về “đã như thế thì”, không chỉ nêu nguyên nhân khách quan. Lưu ý: Không dùng 既然 cho một giả thiết chưa biết đúng hay sai như 如果. Vế đầu thường là thông tin đã được chấp nhận."},{"question":"___你同意，我们就开始。","options":["不管","无论","按照","既然"],"answer":"既然","explanation":"Lấy một sự việc đã được thừa nhận làm tiền đề cho lời đề nghị hoặc kết luận. 既然 thiên về “đã như thế thì”, không chỉ nêu nguyên nhân khách quan. Lưu ý: Không dùng 既然 cho một giả thiết chưa biết đúng hay sai như 如果. Vế đầu thường là thông tin đã được chấp nhận."}]', 'Lỗi thường gặp của người Việt: Không dùng 既然 cho một giả thiết chưa biết đúng hay sai như 如果. Vế đầu thường là thông tin đã được chấp nhận.', 27, 'hsk4-career-society', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Bổ ngữ khả năng', 'V + 得 / 不 + bổ ngữ', 4, 'Biểu thị có hoặc không có khả năng đạt kết quả hoặc thực hiện hướng chuyển động, ví dụ 看得懂 và 看不懂. Mẫu này khác 得 nối bổ ngữ trình độ như 说得很好.', 'Biểu thị có hoặc không có khả năng đạt kết quả hoặc thực hiện hướng chuyển động, ví dụ 看得懂 và 看不懂. Mẫu này khác 得 nối bổ ngữ trình độ như 说得很好.', '[{"zh":"这本书我看得懂。","pinyin":"zhè běn shū wǒ kàn de dǒng 。","vi":"Quyển sách này tôi đọc hiểu được."},{"zh":"声音太小，我听不清楚。","pinyin":"shēng yīn tài xiǎo ， wǒ tīng bù qīng chǔ 。","vi":"Âm thanh nhỏ quá, tôi nghe không rõ."}]', '[{"question":"表示读不懂：这本书我看___懂。","options":["没","很","太","不"],"answer":"不","explanation":"Biểu thị có hoặc không có khả năng đạt kết quả hoặc thực hiện hướng chuyển động, ví dụ 看得懂 và 看不懂. Mẫu này khác 得 nối bổ ngữ trình độ như 说得很好. Lưu ý: Không thay 看不懂 bằng 不看懂 để diễn đạt không hiểu được. Phân biệt phủ định khả năng và phủ định việc đã xảy ra."},{"question":"表示能够理解：这本书我看___懂。","options":["地","了","得","的"],"answer":"得","explanation":"Biểu thị có hoặc không có khả năng đạt kết quả hoặc thực hiện hướng chuyển động, ví dụ 看得懂 và 看不懂. Mẫu này khác 得 nối bổ ngữ trình độ như 说得很好. Lưu ý: Không thay 看不懂 bằng 不看懂 để diễn đạt không hiểu được. Phân biệt phủ định khả năng và phủ định việc đã xảy ra."}]', 'Lỗi thường gặp của người Việt: Không thay 看不懂 bằng 不看懂 để diễn đạt không hiểu được. Phân biệt phủ định khả năng và phủ định việc đã xảy ra.', 28, 'hsk4-career-society', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Phó từ ngữ khí 简直 và 竟然', '简直 + đánh giá / 竟然 + sự việc bất ngờ', 4, '简直 nhấn mạnh đánh giá mạnh của người nói, thường mang sắc thái “thật là”. 竟然 nhấn mạnh sự việc xảy ra ngoài dự đoán.', '简直 nhấn mạnh đánh giá mạnh của người nói, thường mang sắc thái “thật là”. 竟然 nhấn mạnh sự việc xảy ra ngoài dự đoán.', '[{"zh":"这里简直太美了。","pinyin":"zhè lǐ jiǎn zhí tài měi le 。","vi":"Ở đây thật quá đẹp."},{"zh":"他竟然忘了自己的生日。","pinyin":"tā jìng rán wàng le zì jǐ de shēng rì 。","vi":"Không ngờ anh ấy lại quên sinh nhật của mình."}]', '[{"question":"Điền từ nhấn mạnh bất ngờ: 他___忘了自己的生日。","options":["尽管","无论","竟然","按照"],"answer":"竟然","explanation":"简直 nhấn mạnh đánh giá mạnh của người nói, thường mang sắc thái “thật là”. 竟然 nhấn mạnh sự việc xảy ra ngoài dự đoán. Lưu ý: Đừng thay hai từ máy móc: “không ngờ lại quên” thiên về 竟然, còn “thật quá tốt” thiên về 简直."},{"question":"Điền từ nhấn mạnh đánh giá: 这里___太美了。","options":["不管","简直","按照","既然"],"answer":"简直","explanation":"简直 nhấn mạnh đánh giá mạnh của người nói, thường mang sắc thái “thật là”. 竟然 nhấn mạnh sự việc xảy ra ngoài dự đoán. Lưu ý: Đừng thay hai từ máy móc: “không ngờ lại quên” thiên về 竟然, còn “thật quá tốt” thiên về 简直."}]', 'Lỗi thường gặp của người Việt: Đừng thay hai từ máy móc: “không ngờ lại quên” thiên về 竟然, còn “thật quá tốt” thiên về 简直.', 29, 'hsk4-career-society', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Căn cứ với 按照 và 根据', '按照 + yêu cầu / 根据 + căn cứ', 4, '按照 thường nói làm theo quy trình, yêu cầu hoặc tiêu chuẩn. 根据 thường giới thiệu thông tin làm căn cứ suy luận. Hai từ có vùng dùng giao nhau, cần đọc cả câu.', '按照 thường nói làm theo quy trình, yêu cầu hoặc tiêu chuẩn. 根据 thường giới thiệu thông tin làm căn cứ suy luận. Hai từ có vùng dùng giao nhau, cần đọc cả câu.', '[{"zh":"请按照要求填写。","pinyin":"qǐng àn zhào yāo qiú tián xiě 。","vi":"Xin điền theo yêu cầu."},{"zh":"根据天气预报，明天会下雨。","pinyin":"gēn jù tiān qì yù bào ， míng tiān huì xià yǔ 。","vi":"Theo dự báo thời tiết, ngày mai sẽ mưa."}]', '[{"question":"请___要求填写。","options":["无论","按照","既然","尽管"],"answer":"按照","explanation":"按照 thường nói làm theo quy trình, yêu cầu hoặc tiêu chuẩn. 根据 thường giới thiệu thông tin làm căn cứ suy luận. Hai từ có vùng dùng giao nhau, cần đọc cả câu. Lưu ý: Không đặt 根据 ở cuối câu như “theo”. Trong mẫu nêu căn cứ dự đoán, 根据 dẫn danh từ chỉ căn cứ trước mệnh đề kết luận."},{"question":"___天气预报，明天会下雨。","options":["根据","尽管","既然","不管"],"answer":"根据","explanation":"按照 thường nói làm theo quy trình, yêu cầu hoặc tiêu chuẩn. 根据 thường giới thiệu thông tin làm căn cứ suy luận. Hai từ có vùng dùng giao nhau, cần đọc cả câu. Lưu ý: Không đặt 根据 ở cuối câu như “theo”. Trong mẫu nêu căn cứ dự đoán, 根据 dẫn danh từ chỉ căn cứ trước mệnh đề kết luận."}]', 'Lỗi thường gặp của người Việt: Không đặt 根据 ở cuối câu như “theo”. Trong mẫu nêu căn cứ dự đoán, 根据 dẫn danh từ chỉ căn cứ trước mệnh đề kết luận.', 30, 'hsk4-career-society', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Lựa chọn đánh đổi', '宁可…也不… / 与其…不如…', 5, '宁可…也不… nhấn mạnh chấp nhận phương án đầu để tránh phương án sau. 与其…不如… so sánh và đề xuất phương án sau tốt hơn.', '宁可…也不… nhấn mạnh chấp nhận phương án đầu để tránh phương án sau. 与其…不如… so sánh và đề xuất phương án sau tốt hơn.', '[{"zh":"我宁可走路，也不坐他的车。","pinyin":"wǒ nìng kě zǒu lù ， yě bù zuò tā de chē 。","vi":"Tôi thà đi bộ cũng không đi xe của anh ấy."},{"zh":"与其抱怨，不如行动。","pinyin":"yǔ qí bào yuàn ， bù rú xíng dòng 。","vi":"Thay vì than phiền, chi bằng hành động."}]', '[{"question":"与其抱怨，___行动。","options":["不如","也不","而且","何况"],"answer":"不如","explanation":"宁可…也不… nhấn mạnh chấp nhận phương án đầu để tránh phương án sau. 与其…不如… so sánh và đề xuất phương án sau tốt hơn. Lưu ý: Đừng đảo thứ tự phương án: lựa chọn được ưu tiên ở 宁可 đứng vế đầu, ở 不如 đứng vế sau."},{"question":"我宁可走路，___坐他的车。","options":["不如","而且","所以","也不"],"answer":"也不","explanation":"宁可…也不… nhấn mạnh chấp nhận phương án đầu để tránh phương án sau. 与其…不如… so sánh và đề xuất phương án sau tốt hơn. Lưu ý: Đừng đảo thứ tự phương án: lựa chọn được ưu tiên ở 宁可 đứng vế đầu, ở 不如 đứng vế sau."}]', 'Lỗi thường gặp của người Việt: Đừng đảo thứ tự phương án: lựa chọn được ưu tiên ở 宁可 đứng vế đầu, ở 不如 đứng vế sau.', 31, 'hsk5-economy-media', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Đánh giá với 毕竟 / 未免 / 不妨', '毕竟 + lý do / 未免 + 太… / 不妨 + đề nghị', 5, '毕竟 nhắc lý do cần cân nhắc. 未免 thể hiện nhận xét một điều hơi quá mức. 不妨 đưa ra đề nghị nhẹ nhàng rằng thử làm cũng được.', '毕竟 nhắc lý do cần cân nhắc. 未免 thể hiện nhận xét một điều hơi quá mức. 不妨 đưa ra đề nghị nhẹ nhàng rằng thử làm cũng được.', '[{"zh":"他毕竟还是个孩子。","pinyin":"tā bì jìng hái shì gè hái zi 。","vi":"Dù sao nó vẫn còn là trẻ con."},{"zh":"你不妨换个方法。","pinyin":"nǐ bù fáng huàn gè fāng fǎ 。","vi":"Bạn thử đổi phương pháp xem."}]', '[{"question":"Đề nghị thử: 你___换个方法。","options":["未免","毕竟","何况","不妨"],"answer":"不妨","explanation":"毕竟 nhắc lý do cần cân nhắc. 未免 thể hiện nhận xét một điều hơi quá mức. 不妨 đưa ra đề nghị nhẹ nhàng rằng thử làm cũng được. Lưu ý: 不妨 không mang nghĩa cấm đoán của 不许. 未免 thường có sắc thái đánh giá chứ không phải phủ định thông thường."},{"question":"Nhận xét quá sớm: 这样下结论___太早了。","options":["宁可","与其","未免","不妨"],"answer":"未免","explanation":"毕竟 nhắc lý do cần cân nhắc. 未免 thể hiện nhận xét một điều hơi quá mức. 不妨 đưa ra đề nghị nhẹ nhàng rằng thử làm cũng được. Lưu ý: 不妨 không mang nghĩa cấm đoán của 不许. 未免 thường có sắc thái đánh giá chứ không phải phủ định thông thường."}]', 'Lỗi thường gặp của người Việt: 不妨 không mang nghĩa cấm đoán của 不许. 未免 thường có sắc thái đánh giá chứ không phải phủ định thông thường.', 32, 'hsk5-economy-media', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Phản vấn với 尚且 / 何况 / 何必', 'A 尚且…，何况 B / 何必…呢', 5, '尚且…何况… lập luận từ trường hợp nhẹ hơn tới trường hợp mạnh hơn. 何必 đặt vấn đề về sự cần thiết của một hành động, thường mang ý không cần.', '尚且…何况… lập luận từ trường hợp nhẹ hơn tới trường hợp mạnh hơn. 何必 đặt vấn đề về sự cần thiết của một hành động, thường mang ý không cần.', '[{"zh":"大人尚且觉得难，何况孩子呢？","pinyin":"dà rén shàng qiě jué de nán ， hé kuàng hái zi ne ？","vi":"Người lớn còn thấy khó, huống chi trẻ em?"},{"zh":"何必为小事争吵呢？","pinyin":"hé bì wèi xiǎo shì zhēng chǎo ne ？","vi":"Hà tất tranh cãi vì việc nhỏ?"}]', '[{"question":"大人尚且觉得难，___孩子呢？","options":["不如","尽管","何况","但是"],"answer":"何况","explanation":"尚且…何况… lập luận từ trường hợp nhẹ hơn tới trường hợp mạnh hơn. 何必 đặt vấn đề về sự cần thiết của một hành động, thường mang ý không cần. Lưu ý: 何况 không thay được 但是: nó tăng cường lập luận cùng chiều. 何必 thường không đòi một câu trả lời về lý do thực tế."},{"question":"Hỏi có cần thiết không: ___为小事争吵呢？","options":["不妨","何必","何况","尚且"],"answer":"何必","explanation":"尚且…何况… lập luận từ trường hợp nhẹ hơn tới trường hợp mạnh hơn. 何必 đặt vấn đề về sự cần thiết của một hành động, thường mang ý không cần. Lưu ý: 何况 không thay được 但是: nó tăng cường lập luận cùng chiều. 何必 thường không đòi một câu trả lời về lý do thực tế."}]', 'Lỗi thường gặp của người Việt: 何况 không thay được 但是: nó tăng cường lập luận cùng chiều. 何必 thường không đòi một câu trả lời về lý do thực tế.', 33, 'hsk5-economy-media', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Danh từ hóa với 所', '所 + V / S + 所 + V + 的 + N', 5, '所 đứng trước động từ để tạo một cụm mang tính danh từ hoặc định ngữ trong văn viết. Trong mẫu có danh từ trung tâm, thường dùng 的 sau cụm động từ.', '所 đứng trước động từ để tạo một cụm mang tính danh từ hoặc định ngữ trong văn viết. Trong mẫu có danh từ trung tâm, thường dùng 的 sau cụm động từ.', '[{"zh":"这是我所了解的情况。","pinyin":"zhè shì wǒ suǒ liǎo jiě de qíng kuàng 。","vi":"Đây là tình hình mà tôi biết."},{"zh":"他所说的话很重要。","pinyin":"tā suǒ shuō de huà hěn zhòng yào 。","vi":"Những lời anh ấy nói rất quan trọng."}]', '[{"question":"这是我___了解的情况。","options":["比","所","把","被"],"answer":"所","explanation":"所 đứng trước động từ để tạo một cụm mang tính danh từ hoặc định ngữ trong văn viết. Trong mẫu có danh từ trung tâm, thường dùng 的 sau cụm động từ. Lưu ý: Không đặt 所 sau động từ. Không dịch 所 thành nơi chốn trong mọi trường hợp, vì ở đây nó tham gia cấu trúc danh từ hóa."},{"question":"他所说___话很重要。","options":["的","得","地","了"],"answer":"的","explanation":"所 đứng trước động từ để tạo một cụm mang tính danh từ hoặc định ngữ trong văn viết. Trong mẫu có danh từ trung tâm, thường dùng 的 sau cụm động từ. Lưu ý: Không đặt 所 sau động từ. Không dịch 所 thành nơi chốn trong mọi trường hợp, vì ở đây nó tham gia cấu trúc danh từ hóa."}]', 'Lỗi thường gặp của người Việt: Không đặt 所 sau động từ. Không dịch 所 thành nơi chốn trong mọi trường hợp, vì ở đây nó tham gia cấu trúc danh từ hóa.', 34, 'hsk5-economy-media', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Giả định rủi ro với 万一', '万一…，就…', 5, 'Nêu khả năng ngoài ý muốn để chuẩn bị cách xử lý. Không phải mọi điều kiện với 如果 đều thay được bằng 万一, vì 万一 thường có sắc thái đề phòng.', 'Nêu khả năng ngoài ý muốn để chuẩn bị cách xử lý. Không phải mọi điều kiện với 如果 đều thay được bằng 万一, vì 万一 thường có sắc thái đề phòng.', '[{"zh":"万一下雨，我们就在家学习。","pinyin":"wàn yī xià yǔ ， wǒ men jiù zài jiā xué xí 。","vi":"Nhỡ trời mưa, chúng ta học ở nhà."},{"zh":"万一迷路，就给我打电话。","pinyin":"wàn yī mí lù ， jiù gěi wǒ dǎ diàn huà 。","vi":"Nhỡ lạc đường thì gọi điện cho tôi."}]', '[{"question":"___迷路，就给我打电话。","options":["万一","既然","尽管","按照"],"answer":"万一","explanation":"Nêu khả năng ngoài ý muốn để chuẩn bị cách xử lý. Không phải mọi điều kiện với 如果 đều thay được bằng 万一, vì 万一 thường có sắc thái đề phòng. Lưu ý: Không hiểu 万一 là một con số trong mẫu điều kiện. Vế sau cần phù hợp với tình huống dự phòng."},{"question":"万一下雨，我们___在家学习。","options":["虽然","尽管","何况","就"],"answer":"就","explanation":"Nêu khả năng ngoài ý muốn để chuẩn bị cách xử lý. Không phải mọi điều kiện với 如果 đều thay được bằng 万一, vì 万一 thường có sắc thái đề phòng. Lưu ý: Không hiểu 万一 là một con số trong mẫu điều kiện. Vế sau cần phù hợp với tình huống dự phòng."}]', 'Lỗi thường gặp của người Việt: Không hiểu 万一 là một con số trong mẫu điều kiện. Vế sau cần phù hợp với tình huống dự phòng.', 35, 'hsk5-economy-media', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Thành ngữ làm vị ngữ và định ngữ', 'S + thành ngữ / thành ngữ + 的 + N', 5, 'Một số thành ngữ có tính chất tính từ dùng làm vị ngữ hoặc định ngữ. Không phải mọi cụm bốn chữ đều là thành ngữ, và không phải thành ngữ nào cũng dùng ở mọi vị trí.', 'Một số thành ngữ có tính chất tính từ dùng làm vị ngữ hoặc định ngữ. Không phải mọi cụm bốn chữ đều là thành ngữ, và không phải thành ngữ nào cũng dùng ở mọi vị trí.', '[{"zh":"他的安排井井有条。","pinyin":"tā de ān pái jǐng jǐng yǒu tiáo 。","vi":"Sự sắp xếp của anh ấy rất đâu ra đấy."},{"zh":"我们欣赏井井有条的安排。","pinyin":"wǒ men xīn shǎng jǐng jǐng yǒu tiáo de ān pái 。","vi":"Chúng tôi đánh giá cao sự sắp xếp ngăn nắp."}]', '[{"question":"他的安排___，一点儿也不乱。","options":["半途而废","刻舟求剑","自相矛盾","井井有条"],"answer":"井井有条","explanation":"Một số thành ngữ có tính chất tính từ dùng làm vị ngữ hoặc định ngữ. Không phải mọi cụm bốn chữ đều là thành ngữ, và không phải thành ngữ nào cũng dùng ở mọi vị trí. Lưu ý: Không tự ghép bốn chữ thành thành ngữ. Khi làm định ngữ phức tạp trong mẫu này cần 的, ví dụ 井井有条的安排."},{"question":"我们欣赏井井有条___安排。","options":["地","了","的","得"],"answer":"的","explanation":"Một số thành ngữ có tính chất tính từ dùng làm vị ngữ hoặc định ngữ. Không phải mọi cụm bốn chữ đều là thành ngữ, và không phải thành ngữ nào cũng dùng ở mọi vị trí. Lưu ý: Không tự ghép bốn chữ thành thành ngữ. Khi làm định ngữ phức tạp trong mẫu này cần 的, ví dụ 井井有条的安排."}]', 'Lỗi thường gặp của người Việt: Không tự ghép bốn chữ thành thành ngữ. Khi làm định ngữ phức tạp trong mẫu này cần 的, ví dụ 井井有条的安排.', 36, 'hsk5-economy-media', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Căn cứ văn viết với 鉴于', '鉴于 + tình hình，(因此) + quyết định', 6, '鉴于 nêu tình hình được cân nhắc trước một quyết định trong văn phong trang trọng. 因此 có thể nối phần kết quả, không bắt buộc xuất hiện trong mọi câu.', '鉴于 nêu tình hình được cân nhắc trước một quyết định trong văn phong trang trọng. 因此 có thể nối phần kết quả, không bắt buộc xuất hiện trong mọi câu.', '[{"zh":"鉴于天气恶劣，活动取消。","pinyin":"jiàn yú tiān qì è liè ， huó dòng qǔ xiāo 。","vi":"Xét thấy thời tiết xấu, hoạt động bị hủy."},{"zh":"鉴于情况有变，因此需要重新讨论。","pinyin":"jiàn yú qíng kuàng yǒu biàn ， yīn cǐ xū yào chóng xīn tǎo lùn 。","vi":"Xét thấy tình hình thay đổi, vì vậy cần thảo luận lại."}]', '[{"question":"___天气恶劣，活动取消。","options":["无论","何必","鉴于","倘若"],"answer":"鉴于","explanation":"鉴于 nêu tình hình được cân nhắc trước một quyết định trong văn phong trang trọng. 因此 có thể nối phần kết quả, không bắt buộc xuất hiện trong mọi câu. Lưu ý: Không dùng 鉴于 như một động từ mang tân ngữ người. Phần theo sau cần là căn cứ có ý nghĩa cho quyết định."},{"question":"鉴于情况有变，___需要重新讨论。","options":["尚且","因此","尽管","何况"],"answer":"因此","explanation":"鉴于 nêu tình hình được cân nhắc trước một quyết định trong văn phong trang trọng. 因此 có thể nối phần kết quả, không bắt buộc xuất hiện trong mọi câu. Lưu ý: Không dùng 鉴于 như một động từ mang tân ngữ người. Phần theo sau cần là căn cứ có ý nghĩa cho quyết định."}]', 'Lỗi thường gặp của người Việt: Không dùng 鉴于 như một động từ mang tân ngữ người. Phần theo sau cần là căn cứ có ý nghĩa cho quyết định.', 37, 'hsk6-academic-governance', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Giả định trang trọng với 倘若 / 假使', '倘若 / 假使…，便 / 就…', 6, 'Diễn đạt giả thiết trong văn viết hoặc lời nói trang trọng. 倘若 và 假使 có ý gần 如果, vế sau nêu kết quả giả định.', 'Diễn đạt giả thiết trong văn viết hoặc lời nói trang trọng. 倘若 và 假使 có ý gần 如果, vế sau nêu kết quả giả định.', '[{"zh":"倘若有机会，我便去参观。","pinyin":"tǎng ruò yǒu jī huì ， wǒ biàn qù cān guān 。","vi":"Nếu có cơ hội, tôi sẽ đi tham quan."},{"zh":"假使计划失败，我们就重新开始。","pinyin":"jiǎ shǐ jì huà shī bài ， wǒ men jiù chóng xīn kāi shǐ 。","vi":"Giả sử kế hoạch thất bại, chúng ta sẽ bắt đầu lại."}]', '[{"question":"___有机会，我便去参观。","options":["尽管","倘若","既然","鉴于"],"answer":"倘若","explanation":"Diễn đạt giả thiết trong văn viết hoặc lời nói trang trọng. 倘若 và 假使 có ý gần 如果, vế sau nêu kết quả giả định. Lưu ý: Không coi giả thiết là sự việc đã xảy ra. 便 trong mẫu này mang ý thì, không phải nghĩa thuận tiện."},{"question":"假使计划失败，我们___重新开始。","options":["就","尽管","因为","无论"],"answer":"就","explanation":"Diễn đạt giả thiết trong văn viết hoặc lời nói trang trọng. 倘若 và 假使 có ý gần 如果, vế sau nêu kết quả giả định. Lưu ý: Không coi giả thiết là sự việc đã xảy ra. 便 trong mẫu này mang ý thì, không phải nghĩa thuận tiện."}]', 'Lỗi thường gặp của người Việt: Không coi giả thiết là sự việc đã xảy ra. 便 trong mẫu này mang ý thì, không phải nghĩa thuận tiện.', 38, 'hsk6-academic-governance', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Thừa nhận và chuyển ý với 固然', 'A 固然…，不过 / 然而 B…', 6, 'Thừa nhận điểm hợp lý của A rồi bổ sung giới hạn hoặc góc nhìn khác ở B. 固然 thường đặt sau chủ ngữ hoặc ở đầu vế.', 'Thừa nhận điểm hợp lý của A rồi bổ sung giới hạn hoặc góc nhìn khác ở B. 固然 thường đặt sau chủ ngữ hoặc ở đầu vế.', '[{"zh":"经验固然重要，然而学习也不可少。","pinyin":"jīng yàn gù rán zhòng yào ， rán ér xué xí yě bù kě shǎo 。","vi":"Kinh nghiệm cố nhiên quan trọng, tuy nhiên học tập cũng không thể thiếu."},{"zh":"速度固然要紧，不过质量更重要。","pinyin":"sù dù gù rán yào jǐn ， bù guò zhì liàng gèng zhòng yào 。","vi":"Tốc độ cố nhiên cần thiết, nhưng chất lượng quan trọng hơn."}]', '[{"question":"经验___重要，然而学习也不可少。","options":["固然","倘若","不妨","何必"],"answer":"固然","explanation":"Thừa nhận điểm hợp lý của A rồi bổ sung giới hạn hoặc góc nhìn khác ở B. 固然 thường đặt sau chủ ngữ hoặc ở đầu vế. Lưu ý: Không dùng 固然 để khẳng định một kết luận tuyệt đối. Cần đọc vế chuyển ý để hiểu trọng tâm lập luận."},{"question":"速度固然要紧，___质量更重要。","options":["因此","所以","于是","不过"],"answer":"不过","explanation":"Thừa nhận điểm hợp lý của A rồi bổ sung giới hạn hoặc góc nhìn khác ở B. 固然 thường đặt sau chủ ngữ hoặc ở đầu vế. Lưu ý: Không dùng 固然 để khẳng định một kết luận tuyệt đối. Cần đọc vế chuyển ý để hiểu trọng tâm lập luận."}]', 'Lỗi thường gặp của người Việt: Không dùng 固然 để khẳng định một kết luận tuyệt đối. Cần đọc vế chuyển ý để hiểu trọng tâm lập luận.', 39, 'hsk6-academic-governance', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Phủ định kép và giới hạn phạm vi', '未尝不… / 无非是…', 6, '未尝不 dùng hai lớp phủ định để thừa nhận một khả năng hoặc trạng thái với sắc thái dè dặt. 无非是 giới hạn sự việc ở mức “chẳng qua là”, bản thân nó không phải phủ định kép.', '未尝不 dùng hai lớp phủ định để thừa nhận một khả năng hoặc trạng thái với sắc thái dè dặt. 无非是 giới hạn sự việc ở mức “chẳng qua là”, bản thân nó không phải phủ định kép.', '[{"zh":"我未尝不想帮助你。","pinyin":"wǒ wèi cháng bù xiǎng bāng zhù nǐ 。","vi":"Không phải tôi không muốn giúp bạn."},{"zh":"他无非是想获得理解。","pinyin":"tā wú fēi shì xiǎng huò dé lǐ jiě 。","vi":"Anh ấy chẳng qua muốn được thấu hiểu."}]', '[{"question":"Thừa nhận muốn giúp: 我未尝___想帮助你。","options":["没","无","非","不"],"answer":"不","explanation":"未尝不 dùng hai lớp phủ định để thừa nhận một khả năng hoặc trạng thái với sắc thái dè dặt. 无非是 giới hạn sự việc ở mức “chẳng qua là”, bản thân nó không phải phủ định kép. Lưu ý: Không dịch 未尝不 thành hoàn toàn không. Không gộp 无非是 vào cùng quy tắc hai lần phủ định triệt tiêu nhau."},{"question":"Giới hạn “chẳng qua”: 他___是想获得理解。","options":["倘若","岂不","无非","未尝"],"answer":"无非","explanation":"未尝不 dùng hai lớp phủ định để thừa nhận một khả năng hoặc trạng thái với sắc thái dè dặt. 无非是 giới hạn sự việc ở mức “chẳng qua là”, bản thân nó không phải phủ định kép. Lưu ý: Không dịch 未尝不 thành hoàn toàn không. Không gộp 无非是 vào cùng quy tắc hai lần phủ định triệt tiêu nhau."}]', 'Lỗi thường gặp của người Việt: Không dịch 未尝不 thành hoàn toàn không. Không gộp 无非是 vào cùng quy tắc hai lần phủ định triệt tiêu nhau.', 40, 'hsk6-academic-governance', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Phản vấn tu từ với 岂不是', '岂不是…吗？', 6, 'Dùng câu hỏi tu từ để nhấn mạnh nhận định khẳng định, gần với “há chẳng phải… sao”. Sắc thái trang trọng hoặc có tính tranh luận.', 'Dùng câu hỏi tu từ để nhấn mạnh nhận định khẳng định, gần với “há chẳng phải… sao”. Sắc thái trang trọng hoặc có tính tranh luận.', '[{"zh":"这样做岂不是更好吗？","pinyin":"zhè yàng zuò qǐ bù shì gèng hǎo ma ？","vi":"Làm thế này há chẳng tốt hơn sao?"},{"zh":"这岂不是一个机会吗？","pinyin":"zhè qǐ bù shì yí gè jī huì ma ？","vi":"Đây há chẳng phải một cơ hội sao?"}]', '[{"question":"这样做___更好吗？","options":["未免是","不妨是","岂不是","何况是"],"answer":"岂不是","explanation":"Dùng câu hỏi tu từ để nhấn mạnh nhận định khẳng định, gần với “há chẳng phải… sao”. Sắc thái trang trọng hoặc có tính tranh luận. Lưu ý: Không dịch như một câu hỏi xin thông tin trung tính. Nghĩa khẳng định phải được xác định theo ngữ cảnh."},{"question":"这岂不是一个机会___？","options":["地","吗","的","得"],"answer":"吗","explanation":"Dùng câu hỏi tu từ để nhấn mạnh nhận định khẳng định, gần với “há chẳng phải… sao”. Sắc thái trang trọng hoặc có tính tranh luận. Lưu ý: Không dịch như một câu hỏi xin thông tin trung tính. Nghĩa khẳng định phải được xác định theo ngữ cảnh."}]', 'Lỗi thường gặp của người Việt: Không dịch như một câu hỏi xin thông tin trung tính. Nghĩa khẳng định phải được xác định theo ngữ cảnh.', 41, 'hsk6-academic-governance', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md'),
    ('Song hành trong văn nghị luận', '不为…，不为…，只为…', 6, 'Dùng các vế có cấu trúc tương ứng để tạo nhịp và làm rõ quan hệ ý nghĩa. Song hành không đồng nghĩa điển cố: điển cố phải gắn với xuất xứ xác thực, bài này không gán nguồn cho câu tự soạn.', 'Dùng các vế có cấu trúc tương ứng để tạo nhịp và làm rõ quan hệ ý nghĩa. Song hành không đồng nghĩa điển cố: điển cố phải gắn với xuất xứ xác thực, bài này không gán nguồn cho câu tự soạn.', '[{"zh":"不为名，不为利，只为把事情做好。","pinyin":"bù wèi míng ， bù wèi lì ， zhǐ wèi bǎ shì qíng zuò hǎo 。","vi":"Không vì danh, không vì lợi, chỉ để làm tốt công việc."},{"zh":"以事实为依据，以实践为标准。","pinyin":"yǐ shì shí wèi yī jù ， yǐ shí jiàn wèi biāo zhǔn 。","vi":"Lấy sự thật làm căn cứ, lấy thực tiễn làm tiêu chuẩn."}]', '[{"question":"不为名，不为利，___把事情做好。","options":["无论","只为","何况","尽管"],"answer":"只为","explanation":"Dùng các vế có cấu trúc tương ứng để tạo nhịp và làm rõ quan hệ ý nghĩa. Song hành không đồng nghĩa điển cố: điển cố phải gắn với xuất xứ xác thực, bài này không gán nguồn cho câu tự soạn. Lưu ý: Không ép các vế bằng nhau về số chữ nếu làm sai nghĩa. Không tự bịa xuất xứ cổ văn cho một câu hiện đại."},{"question":"以事实为依据，___实践为标准。","options":["以","把","被","比"],"answer":"以","explanation":"Dùng các vế có cấu trúc tương ứng để tạo nhịp và làm rõ quan hệ ý nghĩa. Song hành không đồng nghĩa điển cố: điển cố phải gắn với xuất xứ xác thực, bài này không gán nguồn cho câu tự soạn. Lưu ý: Không ép các vế bằng nhau về số chữ nếu làm sai nghĩa. Không tự bịa xuất xứ cổ văn cho một câu hiện đại."}]', 'Lỗi thường gặp của người Việt: Không ép các vế bằng nhau về số chữ nếu làm sai nghĩa. Không tự bịa xuất xứ cổ văn cho một câu hiện đại.', 42, 'hsk6-academic-governance', 'APPROVED', 'M6:original;see docs/m6-curriculum-sources.md')
) AS r(title,structure,hsk_level,explanation_vi,explanation,examples_json,exercises_json,notes,order_index,lesson_slug,review_status,source_ref)
JOIN lessons l ON l.slug=r.lesson_slug
WHERE NOT EXISTS (SELECT 1 FROM grammar_rules old WHERE old.title=r.title);

INSERT INTO grammar_exercises (grammar_rule_id,question_text,options_json,correct_answer,explanation,is_common_mistake,mistake_category,review_status,needs_human_check,source_ref)
SELECT gr.id,e.question_text,e.options_json,e.correct_answer,e.explanation,e.is_common_mistake,e.mistake_category,e.review_status,e.needs_human_check,e.source_ref
FROM (VALUES
    ('Câu chữ 把', '请___门关上。', '["把","被","比","从"]', '把', 'Đưa tân ngữ đã xác định lên trước động từ để nói cách xử lý và kết quả tác động lên nó. Động từ thường cần thêm kết quả, vị trí hoặc thành phần hoàn thành. Lưu ý: Không dịch mọi câu “lấy” thành 把. Không để câu kết thúc bằng một động từ trần khi chưa diễn đạt kết quả xử lý.', false, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Câu chữ 把', '我把作业写___了。', '["在","从","给","完"]', '完', 'Đưa tân ngữ đã xác định lên trước động từ để nói cách xử lý và kết quả tác động lên nó. Động từ thường cần thêm kết quả, vị trí hoặc thành phần hoàn thành. Lưu ý: Không dịch mọi câu “lấy” thành 把. Không để câu kết thúc bằng một động từ trần khi chưa diễn đạt kết quả xử lý.', true, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Câu bị động với 被', '门___风吹开了。', '["把","给","比","被"]', '被', 'Đặt đối tượng chịu tác động làm chủ ngữ. Tác nhân sau 被 có thể được lược bỏ khi ngữ cảnh rõ. Câu thường có thành phần diễn đạt kết quả. Lưu ý: Chủ ngữ là đối tượng chịu tác động, không phải người thực hiện. Phủ định 没 đứng trước 被.', false, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Câu bị động với 被', '我的书___被拿走。', '["比","从","没","把"]', '没', 'Đặt đối tượng chịu tác động làm chủ ngữ. Tác nhân sau 被 có thể được lược bỏ khi ngữ cảnh rõ. Câu thường có thành phần diễn đạt kết quả. Lưu ý: Chủ ngữ là đối tượng chịu tác động, không phải người thực hiện. Phủ định 没 đứng trước 被.', true, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Bổ ngữ xu hướng kép', '他从房间里走___。', '["不上","得很","出来","进去"]', '出来', 'Bổ ngữ xu hướng mô tả hướng chuyển động so với vị trí người nói. Một số tổ hợp còn chỉ bắt đầu hoặc tiếp tục một trạng thái, cần đọc theo ngữ cảnh. Lưu ý: Không dịch 来 và 去 đơn thuần là thời tương lai. 来 thường hướng về người nói, 去 hướng ra xa người nói.', false, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Bổ ngữ xu hướng kép', '故事还没结束，请继续说___。', '["得","下去","上来","不过"]', '下去', 'Bổ ngữ xu hướng mô tả hướng chuyển động so với vị trí người nói. Một số tổ hợp còn chỉ bắt đầu hoặc tiếp tục một trạng thái, cần đọc theo ngữ cảnh. Lưu ý: Không dịch 来 và 去 đơn thuần là thời tương lai. 来 thường hướng về người nói, 去 hướng ra xa người nói.', true, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Loại trừ và bổ sung với 除了', '除了小王以外，大家___来了。', '["的","都","把","被"]', '都', '除了…以外 nêu phạm vi ngoại lệ hoặc bổ sung. 都 thường dẫn phần còn lại trong câu loại trừ, còn 还 hoặc 也 thường bổ sung đối tượng hoặc hoạt động khác. Lưu ý: Đừng luôn dịch 除了 là “trừ”. Cần dựa vào 都 hay 还 và ngữ cảnh để xác định loại trừ hoặc bổ sung.', false, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Loại trừ và bổ sung với 除了', '除了汉语以外，我___学英语。', '["还","把","被","地"]', '还', '除了…以外 nêu phạm vi ngoại lệ hoặc bổ sung. 都 thường dẫn phần còn lại trong câu loại trừ, còn 还 hoặc 也 thường bổ sung đối tượng hoặc hoạt động khác. Lưu ý: Đừng luôn dịch 除了 là “trừ”. Cần dựa vào 都 hay 还 và ngữ cảnh để xác định loại trừ hoặc bổ sung.', true, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Tăng tiến với 越', '天气___冷了。', '["越来越","很越","越很","越来"]', '越来越', '越来越 nêu sự thay đổi tăng dần theo thời gian. 越 A 越 B cho biết mức độ của B thay đổi theo mức độ hoặc hoạt động A. Lưu ý: Không chèn 很 ngay sau 越来越. Trong 越 A 越 B phải giữ cả hai chữ 越.', false, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Tăng tiến với 越', '这本书越看___有意思。', '["很越","比","把","越"]', '越', '越来越 nêu sự thay đổi tăng dần theo thời gian. 越 A 越 B cho biết mức độ của B thay đổi theo mức độ hoặc hoạt động A. Lưu ý: Không chèn 很 ngay sau 越来越. Trong 越 A 越 B phải giữ cả hai chữ 越.', true, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Không những… mà còn…', '她不但会说汉语，___会写汉字。', '["但是","所以","因为","而且"]', '而且', 'Nối hai đặc điểm hoặc sự việc theo quan hệ bổ sung tăng tiến. Khi hai vế cùng chủ ngữ, chủ ngữ thường đặt trước 不但. Khi khác chủ ngữ, 不但 có thể đứng trước chủ ngữ thứ nhất. Lưu ý: Đừng dùng 但是 thay 而且 khi hai vế cùng chiều bổ sung, không có ý đối lập.', false, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Không những… mà còn…', '___我喜欢，妹妹也喜欢。', '["被","比","不但","把"]', '不但', 'Nối hai đặc điểm hoặc sự việc theo quan hệ bổ sung tăng tiến. Khi hai vế cùng chủ ngữ, chủ ngữ thường đặt trước 不但. Khi khác chủ ngữ, 不但 có thể đứng trước chủ ngữ thứ nhất. Lưu ý: Đừng dùng 但是 thay 而且 khi hai vế cùng chiều bổ sung, không có ý đối lập.', true, 'M6:HSK3', 'APPROVED', false, 'M6:original-practice'),
    ('Nhượng bộ với 尽管', '___下雨，他还是出门了。', '["既然","按照","尽管","因为"]', '尽管', 'Thừa nhận một điều kiện đã có rồi nêu kết quả trái với điều thường dự đoán. 尽管 cũng có cách dùng cho phép cứ làm, bài này tập trung vào quan hệ nhượng bộ. Lưu ý: Không suy ra kết quả tất yếu như 因为…所以. Vế sau cần có ý ngược với kỳ vọng từ vế trước.', false, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Nhượng bộ với 尽管', '尽管很累，他___坚持工作。', '["因为","还是","所以","因此"]', '还是', 'Thừa nhận một điều kiện đã có rồi nêu kết quả trái với điều thường dự đoán. 尽管 cũng có cách dùng cho phép cứ làm, bài này tập trung vào quan hệ nhượng bộ. Lưu ý: Không suy ra kết quả tất yếu như 因为…所以. Vế sau cần có ý ngược với kỳ vọng từ vế trước.', true, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Bất kể với 不管 / 无论', '不管多忙，我___每天读书。', '["的","都","把","被"]', '都', 'Khẳng định kết quả không đổi trước các khả năng khác nhau. Điều kiện thường dùng từ nghi vấn phiếm chỉ như 谁, 怎么, 多… hoặc hai phương án đối lập. Lưu ý: Không bỏ 都 trong mẫu luyện này. Đừng nhầm 谁 trong 无论谁 với một câu hỏi trực tiếp.', false, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Bất kể với 不管 / 无论', '___谁来，我们都欢迎。', '["无论","既然","按照","因为"]', '无论', 'Khẳng định kết quả không đổi trước các khả năng khác nhau. Điều kiện thường dùng từ nghi vấn phiếm chỉ như 谁, 怎么, 多… hoặc hai phương án đối lập. Lưu ý: Không bỏ 都 trong mẫu luyện này. Đừng nhầm 谁 trong 无论谁 với một câu hỏi trực tiếp.', true, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Suy luận với 既然', '既然来了，___坐一会儿吧。', '["就","因为","虽然","尽管"]', '就', 'Lấy một sự việc đã được thừa nhận làm tiền đề cho lời đề nghị hoặc kết luận. 既然 thiên về “đã như thế thì”, không chỉ nêu nguyên nhân khách quan. Lưu ý: Không dùng 既然 cho một giả thiết chưa biết đúng hay sai như 如果. Vế đầu thường là thông tin đã được chấp nhận.', false, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Suy luận với 既然', '___你同意，我们就开始。', '["不管","无论","按照","既然"]', '既然', 'Lấy một sự việc đã được thừa nhận làm tiền đề cho lời đề nghị hoặc kết luận. 既然 thiên về “đã như thế thì”, không chỉ nêu nguyên nhân khách quan. Lưu ý: Không dùng 既然 cho một giả thiết chưa biết đúng hay sai như 如果. Vế đầu thường là thông tin đã được chấp nhận.', true, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Bổ ngữ khả năng', '表示读不懂：这本书我看___懂。', '["没","很","太","不"]', '不', 'Biểu thị có hoặc không có khả năng đạt kết quả hoặc thực hiện hướng chuyển động, ví dụ 看得懂 và 看不懂. Mẫu này khác 得 nối bổ ngữ trình độ như 说得很好. Lưu ý: Không thay 看不懂 bằng 不看懂 để diễn đạt không hiểu được. Phân biệt phủ định khả năng và phủ định việc đã xảy ra.', false, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Bổ ngữ khả năng', '表示能够理解：这本书我看___懂。', '["地","了","得","的"]', '得', 'Biểu thị có hoặc không có khả năng đạt kết quả hoặc thực hiện hướng chuyển động, ví dụ 看得懂 và 看不懂. Mẫu này khác 得 nối bổ ngữ trình độ như 说得很好. Lưu ý: Không thay 看不懂 bằng 不看懂 để diễn đạt không hiểu được. Phân biệt phủ định khả năng và phủ định việc đã xảy ra.', true, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Phó từ ngữ khí 简直 và 竟然', 'Điền từ nhấn mạnh bất ngờ: 他___忘了自己的生日。', '["尽管","无论","竟然","按照"]', '竟然', '简直 nhấn mạnh đánh giá mạnh của người nói, thường mang sắc thái “thật là”. 竟然 nhấn mạnh sự việc xảy ra ngoài dự đoán. Lưu ý: Đừng thay hai từ máy móc: “không ngờ lại quên” thiên về 竟然, còn “thật quá tốt” thiên về 简直.', false, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Phó từ ngữ khí 简直 và 竟然', 'Điền từ nhấn mạnh đánh giá: 这里___太美了。', '["不管","简直","按照","既然"]', '简直', '简直 nhấn mạnh đánh giá mạnh của người nói, thường mang sắc thái “thật là”. 竟然 nhấn mạnh sự việc xảy ra ngoài dự đoán. Lưu ý: Đừng thay hai từ máy móc: “không ngờ lại quên” thiên về 竟然, còn “thật quá tốt” thiên về 简直.', true, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Căn cứ với 按照 và 根据', '请___要求填写。', '["无论","按照","既然","尽管"]', '按照', '按照 thường nói làm theo quy trình, yêu cầu hoặc tiêu chuẩn. 根据 thường giới thiệu thông tin làm căn cứ suy luận. Hai từ có vùng dùng giao nhau, cần đọc cả câu. Lưu ý: Không đặt 根据 ở cuối câu như “theo”. Trong mẫu nêu căn cứ dự đoán, 根据 dẫn danh từ chỉ căn cứ trước mệnh đề kết luận.', false, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Căn cứ với 按照 và 根据', '___天气预报，明天会下雨。', '["根据","尽管","既然","不管"]', '根据', '按照 thường nói làm theo quy trình, yêu cầu hoặc tiêu chuẩn. 根据 thường giới thiệu thông tin làm căn cứ suy luận. Hai từ có vùng dùng giao nhau, cần đọc cả câu. Lưu ý: Không đặt 根据 ở cuối câu như “theo”. Trong mẫu nêu căn cứ dự đoán, 根据 dẫn danh từ chỉ căn cứ trước mệnh đề kết luận.', true, 'M6:HSK4', 'APPROVED', false, 'M6:original-practice'),
    ('Lựa chọn đánh đổi', '与其抱怨，___行动。', '["不如","也不","而且","何况"]', '不如', '宁可…也不… nhấn mạnh chấp nhận phương án đầu để tránh phương án sau. 与其…不如… so sánh và đề xuất phương án sau tốt hơn. Lưu ý: Đừng đảo thứ tự phương án: lựa chọn được ưu tiên ở 宁可 đứng vế đầu, ở 不如 đứng vế sau.', false, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Lựa chọn đánh đổi', '我宁可走路，___坐他的车。', '["不如","而且","所以","也不"]', '也不', '宁可…也不… nhấn mạnh chấp nhận phương án đầu để tránh phương án sau. 与其…不如… so sánh và đề xuất phương án sau tốt hơn. Lưu ý: Đừng đảo thứ tự phương án: lựa chọn được ưu tiên ở 宁可 đứng vế đầu, ở 不如 đứng vế sau.', true, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Đánh giá với 毕竟 / 未免 / 不妨', 'Đề nghị thử: 你___换个方法。', '["未免","毕竟","何况","不妨"]', '不妨', '毕竟 nhắc lý do cần cân nhắc. 未免 thể hiện nhận xét một điều hơi quá mức. 不妨 đưa ra đề nghị nhẹ nhàng rằng thử làm cũng được. Lưu ý: 不妨 không mang nghĩa cấm đoán của 不许. 未免 thường có sắc thái đánh giá chứ không phải phủ định thông thường.', false, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Đánh giá với 毕竟 / 未免 / 不妨', 'Nhận xét quá sớm: 这样下结论___太早了。', '["宁可","与其","未免","不妨"]', '未免', '毕竟 nhắc lý do cần cân nhắc. 未免 thể hiện nhận xét một điều hơi quá mức. 不妨 đưa ra đề nghị nhẹ nhàng rằng thử làm cũng được. Lưu ý: 不妨 không mang nghĩa cấm đoán của 不许. 未免 thường có sắc thái đánh giá chứ không phải phủ định thông thường.', true, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Phản vấn với 尚且 / 何况 / 何必', '大人尚且觉得难，___孩子呢？', '["不如","尽管","何况","但是"]', '何况', '尚且…何况… lập luận từ trường hợp nhẹ hơn tới trường hợp mạnh hơn. 何必 đặt vấn đề về sự cần thiết của một hành động, thường mang ý không cần. Lưu ý: 何况 không thay được 但是: nó tăng cường lập luận cùng chiều. 何必 thường không đòi một câu trả lời về lý do thực tế.', false, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Phản vấn với 尚且 / 何况 / 何必', 'Hỏi có cần thiết không: ___为小事争吵呢？', '["不妨","何必","何况","尚且"]', '何必', '尚且…何况… lập luận từ trường hợp nhẹ hơn tới trường hợp mạnh hơn. 何必 đặt vấn đề về sự cần thiết của một hành động, thường mang ý không cần. Lưu ý: 何况 không thay được 但是: nó tăng cường lập luận cùng chiều. 何必 thường không đòi một câu trả lời về lý do thực tế.', true, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Danh từ hóa với 所', '这是我___了解的情况。', '["比","所","把","被"]', '所', '所 đứng trước động từ để tạo một cụm mang tính danh từ hoặc định ngữ trong văn viết. Trong mẫu có danh từ trung tâm, thường dùng 的 sau cụm động từ. Lưu ý: Không đặt 所 sau động từ. Không dịch 所 thành nơi chốn trong mọi trường hợp, vì ở đây nó tham gia cấu trúc danh từ hóa.', false, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Danh từ hóa với 所', '他所说___话很重要。', '["的","得","地","了"]', '的', '所 đứng trước động từ để tạo một cụm mang tính danh từ hoặc định ngữ trong văn viết. Trong mẫu có danh từ trung tâm, thường dùng 的 sau cụm động từ. Lưu ý: Không đặt 所 sau động từ. Không dịch 所 thành nơi chốn trong mọi trường hợp, vì ở đây nó tham gia cấu trúc danh từ hóa.', true, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Giả định rủi ro với 万一', '___迷路，就给我打电话。', '["万一","既然","尽管","按照"]', '万一', 'Nêu khả năng ngoài ý muốn để chuẩn bị cách xử lý. Không phải mọi điều kiện với 如果 đều thay được bằng 万一, vì 万一 thường có sắc thái đề phòng. Lưu ý: Không hiểu 万一 là một con số trong mẫu điều kiện. Vế sau cần phù hợp với tình huống dự phòng.', false, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Giả định rủi ro với 万一', '万一下雨，我们___在家学习。', '["虽然","尽管","何况","就"]', '就', 'Nêu khả năng ngoài ý muốn để chuẩn bị cách xử lý. Không phải mọi điều kiện với 如果 đều thay được bằng 万一, vì 万一 thường có sắc thái đề phòng. Lưu ý: Không hiểu 万一 là một con số trong mẫu điều kiện. Vế sau cần phù hợp với tình huống dự phòng.', true, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Thành ngữ làm vị ngữ và định ngữ', '他的安排___，一点儿也不乱。', '["半途而废","刻舟求剑","自相矛盾","井井有条"]', '井井有条', 'Một số thành ngữ có tính chất tính từ dùng làm vị ngữ hoặc định ngữ. Không phải mọi cụm bốn chữ đều là thành ngữ, và không phải thành ngữ nào cũng dùng ở mọi vị trí. Lưu ý: Không tự ghép bốn chữ thành thành ngữ. Khi làm định ngữ phức tạp trong mẫu này cần 的, ví dụ 井井有条的安排.', false, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Thành ngữ làm vị ngữ và định ngữ', '我们欣赏井井有条___安排。', '["地","了","的","得"]', '的', 'Một số thành ngữ có tính chất tính từ dùng làm vị ngữ hoặc định ngữ. Không phải mọi cụm bốn chữ đều là thành ngữ, và không phải thành ngữ nào cũng dùng ở mọi vị trí. Lưu ý: Không tự ghép bốn chữ thành thành ngữ. Khi làm định ngữ phức tạp trong mẫu này cần 的, ví dụ 井井有条的安排.', true, 'M6:HSK5', 'APPROVED', false, 'M6:original-practice'),
    ('Căn cứ văn viết với 鉴于', '___天气恶劣，活动取消。', '["无论","何必","鉴于","倘若"]', '鉴于', '鉴于 nêu tình hình được cân nhắc trước một quyết định trong văn phong trang trọng. 因此 có thể nối phần kết quả, không bắt buộc xuất hiện trong mọi câu. Lưu ý: Không dùng 鉴于 như một động từ mang tân ngữ người. Phần theo sau cần là căn cứ có ý nghĩa cho quyết định.', false, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Căn cứ văn viết với 鉴于', '鉴于情况有变，___需要重新讨论。', '["尚且","因此","尽管","何况"]', '因此', '鉴于 nêu tình hình được cân nhắc trước một quyết định trong văn phong trang trọng. 因此 có thể nối phần kết quả, không bắt buộc xuất hiện trong mọi câu. Lưu ý: Không dùng 鉴于 như một động từ mang tân ngữ người. Phần theo sau cần là căn cứ có ý nghĩa cho quyết định.', true, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Giả định trang trọng với 倘若 / 假使', '___有机会，我便去参观。', '["尽管","倘若","既然","鉴于"]', '倘若', 'Diễn đạt giả thiết trong văn viết hoặc lời nói trang trọng. 倘若 và 假使 có ý gần 如果, vế sau nêu kết quả giả định. Lưu ý: Không coi giả thiết là sự việc đã xảy ra. 便 trong mẫu này mang ý thì, không phải nghĩa thuận tiện.', false, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Giả định trang trọng với 倘若 / 假使', '假使计划失败，我们___重新开始。', '["就","尽管","因为","无论"]', '就', 'Diễn đạt giả thiết trong văn viết hoặc lời nói trang trọng. 倘若 và 假使 có ý gần 如果, vế sau nêu kết quả giả định. Lưu ý: Không coi giả thiết là sự việc đã xảy ra. 便 trong mẫu này mang ý thì, không phải nghĩa thuận tiện.', true, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Thừa nhận và chuyển ý với 固然', '经验___重要，然而学习也不可少。', '["固然","倘若","不妨","何必"]', '固然', 'Thừa nhận điểm hợp lý của A rồi bổ sung giới hạn hoặc góc nhìn khác ở B. 固然 thường đặt sau chủ ngữ hoặc ở đầu vế. Lưu ý: Không dùng 固然 để khẳng định một kết luận tuyệt đối. Cần đọc vế chuyển ý để hiểu trọng tâm lập luận.', false, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Thừa nhận và chuyển ý với 固然', '速度固然要紧，___质量更重要。', '["因此","所以","于是","不过"]', '不过', 'Thừa nhận điểm hợp lý của A rồi bổ sung giới hạn hoặc góc nhìn khác ở B. 固然 thường đặt sau chủ ngữ hoặc ở đầu vế. Lưu ý: Không dùng 固然 để khẳng định một kết luận tuyệt đối. Cần đọc vế chuyển ý để hiểu trọng tâm lập luận.', true, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Phủ định kép và giới hạn phạm vi', 'Thừa nhận muốn giúp: 我未尝___想帮助你。', '["没","无","非","不"]', '不', '未尝不 dùng hai lớp phủ định để thừa nhận một khả năng hoặc trạng thái với sắc thái dè dặt. 无非是 giới hạn sự việc ở mức “chẳng qua là”, bản thân nó không phải phủ định kép. Lưu ý: Không dịch 未尝不 thành hoàn toàn không. Không gộp 无非是 vào cùng quy tắc hai lần phủ định triệt tiêu nhau.', false, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Phủ định kép và giới hạn phạm vi', 'Giới hạn “chẳng qua”: 他___是想获得理解。', '["倘若","岂不","无非","未尝"]', '无非', '未尝不 dùng hai lớp phủ định để thừa nhận một khả năng hoặc trạng thái với sắc thái dè dặt. 无非是 giới hạn sự việc ở mức “chẳng qua là”, bản thân nó không phải phủ định kép. Lưu ý: Không dịch 未尝不 thành hoàn toàn không. Không gộp 无非是 vào cùng quy tắc hai lần phủ định triệt tiêu nhau.', true, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Phản vấn tu từ với 岂不是', '这样做___更好吗？', '["未免是","不妨是","岂不是","何况是"]', '岂不是', 'Dùng câu hỏi tu từ để nhấn mạnh nhận định khẳng định, gần với “há chẳng phải… sao”. Sắc thái trang trọng hoặc có tính tranh luận. Lưu ý: Không dịch như một câu hỏi xin thông tin trung tính. Nghĩa khẳng định phải được xác định theo ngữ cảnh.', false, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Phản vấn tu từ với 岂不是', '这岂不是一个机会___？', '["地","吗","的","得"]', '吗', 'Dùng câu hỏi tu từ để nhấn mạnh nhận định khẳng định, gần với “há chẳng phải… sao”. Sắc thái trang trọng hoặc có tính tranh luận. Lưu ý: Không dịch như một câu hỏi xin thông tin trung tính. Nghĩa khẳng định phải được xác định theo ngữ cảnh.', true, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Song hành trong văn nghị luận', '不为名，不为利，___把事情做好。', '["无论","只为","何况","尽管"]', '只为', 'Dùng các vế có cấu trúc tương ứng để tạo nhịp và làm rõ quan hệ ý nghĩa. Song hành không đồng nghĩa điển cố: điển cố phải gắn với xuất xứ xác thực, bài này không gán nguồn cho câu tự soạn. Lưu ý: Không ép các vế bằng nhau về số chữ nếu làm sai nghĩa. Không tự bịa xuất xứ cổ văn cho một câu hiện đại.', false, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice'),
    ('Song hành trong văn nghị luận', '以事实为依据，___实践为标准。', '["以","把","被","比"]', '以', 'Dùng các vế có cấu trúc tương ứng để tạo nhịp và làm rõ quan hệ ý nghĩa. Song hành không đồng nghĩa điển cố: điển cố phải gắn với xuất xứ xác thực, bài này không gán nguồn cho câu tự soạn. Lưu ý: Không ép các vế bằng nhau về số chữ nếu làm sai nghĩa. Không tự bịa xuất xứ cổ văn cho một câu hiện đại.', true, 'M6:HSK6', 'APPROVED', false, 'M6:original-practice')
) AS e(title,question_text,options_json,correct_answer,explanation,is_common_mistake,mistake_category,review_status,needs_human_check,source_ref)
JOIN grammar_rules gr ON gr.title=e.title
WHERE NOT EXISTS (SELECT 1 FROM grammar_exercises old WHERE old.grammar_rule_id=gr.id AND old.question_text=e.question_text);

